		lines.push(`${g.group.name || g.group.id}${key}: H Ratio ${g.h.ratio.toFixed(3)}, V Ratio ${g.v.ratio.toFixed(3)}  ->  ${g.h.footprint} x ${g.v.footprint} canvas px`);
